"""Mutation tests for source-derived equal-bound honesty dispatch."""

import importlib
import unittest


HONESTY = importlib.import_module("bench.pari-class-group-port.honesty_equal_bound")


class EqualBoundHonestyTest(unittest.TestCase):
    def setUp(self):
        # Generated by the authenticated resident factor-base preparation for
        # x^3 - 20018*x + 20034, including its exact support product.
        self.factor_base = [
            333,
            333,
            66,
            48,
            48,
            66,
            33305723793961172309794353671961864459781409056283352022593315566492501865020800513844122052778,
        ]
        self.preparation = [7, 0, 66, 48, 4, 1833, 2270, 66]

    def test_authentic_h1_cubic_skips_from_equal_generated_counts(self):
        decision = HONESTY.pari_honesty_dispatch_from_factor_base(
            self.factor_base, self.preparation
        )
        self.assertEqual(decision.unchecked_groups, 0)
        self.assertFalse(decision.requires_honesty)
        self.assertEqual(decision.status, "equal-bound-source-skip")
        self.assertEqual((decision.relation_bound, decision.checking_bound), (333, 333))

    def test_mutated_checking_count_requires_real_honesty(self):
        changed = self.factor_base.copy()
        changed[4] = 49
        decision = HONESTY.pari_honesty_dispatch_from_factor_base(
            changed, self.preparation
        )
        self.assertEqual(decision.unchecked_groups, 1)
        self.assertTrue(decision.requires_honesty)
        self.assertEqual(decision.status, "honesty-required")

    def test_bound_labels_do_not_override_the_source_count_predicate(self):
        changed = self.factor_base.copy()
        changed[1] = 334
        decision = HONESTY.pari_honesty_dispatch_from_factor_base(
            changed, self.preparation
        )
        self.assertFalse(decision.requires_honesty)

    def test_copied_preparation_counters_are_authenticated(self):
        changed = self.preparation.copy()
        changed[3] = 47
        with self.assertRaisesRegex(ValueError, "unauthenticated"):
            HONESTY.pari_honesty_dispatch_from_factor_base(self.factor_base, changed)

    def test_nonmonotone_counts_fail_closed_without_mutation(self):
        base = self.factor_base.copy()
        preparation = self.preparation.copy()
        changed = base.copy()
        changed[4] = 47
        with self.assertRaisesRegex(ValueError, "invalid factor-base"):
            HONESTY.pari_honesty_dispatch_from_factor_base(changed, preparation)
        self.assertEqual(self.factor_base, base)
        self.assertEqual(self.preparation, preparation)


if __name__ == "__main__":
    unittest.main()
